class Solution:
    def maxBalancedSubsequenceSum(self, nums: List[int]) -> int:
        n = len(nums)
        maxleft = {}  # dictionary mapping key (nums[i] - i) to max sum ending at that key

        for i in range(n):
            key = nums[i] - i

            if key in maxleft:
                maxleft[key] = max(maxleft[key], nums[i], maxleft[key] + nums[i])
            else:
                # Find largest index previdx such that key (nums[previdx] - previdx) <= current key
                sorted_keys = sorted(maxleft.keys())
                previdx = bisect.bisect_left(sorted_keys, key) - 1
                if previdx < 0:
                    maxleft[key] = nums[i]
                else:
                    prev_key = sorted_keys[previdx]
                    prev_val = maxleft[prev_key]
                    maxleft[key] = max(nums[i], prev_val + nums[i])

            # Find smallest index nextidx such that key (nums[nextidx] - nextidx) > current key
            sorted_keys = sorted(maxleft.keys())
            nextidx = bisect.bisect_right(sorted_keys, key)
            if nextidx < len(sorted_keys) and sorted_keys[nextidx] > key:
                next_key = sorted_keys[nextidx]
                if maxleft[next_key] <= key:
                    del maxleft[next_key]

        return max(maxleft.values()) if maxleft else 0

